debugger;
(function() {
    var redirectPage = decodeURIComponent(document.getElementById("loginRedirect").value);
	redirectPage = decrypt(redirectPage);
    console.log("Redirect page is:"+redirectPage);
    if(redirectPage !== "" && redirectPage !== undefined){
        var pathname = window.location.pathname;
        if (redirectPage.includes("/v3offline/ui/")) {
            var mcaFoOffline = window.open(redirectPage, "mcafo-offline");
            mcaFoOffline.focus();
            var documentReferrer = document.referrer;
            if (documentReferrer !== "" && documentReferrer !== undefined && !documentReferrer.includes(pathname)) {
                window.setTimeout(function() { window.location.href = documentReferrer; }, 10000);
            }
        } else if (!redirectPage.includes(pathname)) {
            window.location.href = redirectPage;
        }
    }
})();